\caption{Construct MPDAG \citep{perkovic2017interpreting, meek1995causal}}
\label{alg: ConstructMPDAG}
\begin{algorithmic}[1]
\State {\bfseries Inputs:} MPDAG $\mathcal{G}$ and Background knowledge $\mathcal{B}$.
\State {\bfseries Output:} MPDAG $\mathcal{G'}$ or FAIL.
\State Let $\mathcal{G'}=\mathcal{G}$;
\While{$\mathcal{B} \neq \emptyset$}
    \State Select an edge $\{S \rightarrow T\}$ in $\mathcal{B}$;
    \State $\mathcal{B} = \mathcal{B} \backslash \{S \rightarrow T\}$;
    \If{$\{S-T\}$ OR $\{S\rightarrow T\}$ is in $\mathcal{G'}$}
        \State Orient $\{S\rightarrow T\}$ in $\mathcal{G'}$;
        \State Orienting edges in $\mathcal{G'}$ following the rules in Figure \ref{fig: orientation_rule} until no edge can be oriented;
    \Else
        \State FAIL;
    \EndIf
\EndWhile
\end{algorithmic}

\citep[Lemma 3.6]{perkovic2017interpreting}
\label{lem: perkovic2017interpreting/Lemma_3.6}
    Let $S$ and $T$ be distinct nodes in an MPDAG $\mathcal{G}$. If $p$ is a b-possibly causal path from $S$ to $T$ in $\mathcal{G}$, then a subsequence $p^*$ of $p$ forms a b-possibly causal unshielded path from $S$ to $T$ in $\mathcal{G}$.

\citep[Theorem 1]{fang2020ida}
\label{theo: fang2020ida/Theorem_1}
\label{theo: fang2020ida/parental_set}
    Let $\mathcal{G}$ be an MPDAG consistent with a CPDAG $\mathcal{G^*}$. For any vertex $X$ and $\mathbf{R}\subset{sib(X, \mathcal{G})}$, the following three statements are equivalent.
    \begin{itemize}[leftmargin=*]
    \itemsep0em
        \item There is a DAG $\mathcal{D} \in [\mathcal{G}]$ such that $pa(X,\mathcal{D})=\mathbf{R} \cup pa(X, \mathcal{G})$ and $ch(X,\mathcal{D}) = sib(X,\mathcal{G}) \cup ch(X,\mathcal{G}) \backslash \mathbf{R}$.
        \item Compared with $\mathcal{G}$, $\mathcal{G}_{\mathbf{R} \rightarrow X}$ does not introduce any new V-structure collided on X or any directed triangle containing $X$.
        \item The induced subgraph of $\mathcal{G}$ over $\mathbf{R}$ is complete, and there does not exist an $R \in \mathbf{R}$ and a $W \in adj(X, \mathcal{G}) \backslash (\mathbf{R} \cup pa(X, \mathcal{G}))$ such that $W \rightarrow R$.
    \end{itemize}

 \citep[Theorem 1]{fang2022local}
\label{theo: fang2021local/CPDAG}
    Suppose that $\mathcal{G^*}$ is a CPDAG, $S$ and $T$ are two distinct vertices in $\mathcal{G^*}$, and $\mathbf{C}$ is the critical set of $S$ with respect to $T$ in $\mathcal{G^*}$. Then, $T$ is a definite descendant of $S$ if and only if $\mathbf{C} \cap{ch(S, \mathcal G^*)} \ne \emptyset$, or $\mathbf{C}$ is non-empty and induces an incomplete subgraph of $\mathcal{G^*}$.

 \citep[Lemma 3.1]{maathuis2009estimating}
\label{lem: maathuis2009estimating}
    Given a CPDAG $\mathcal{G^*}$, a variable $X$, and $R \subset{sib(X, \mathcal{G^*})}$, orienting $R \rightarrow X$ for each $R \in \mathbf{R}$ and $X \rightarrow W$ for each $W \in sib(S,\mathcal{G^*}) \backslash \mathbf{R}$ is consistent with $\mathcal{G^*}$ if and only if new orientations do not introduce v-structures collided on $X$.

Suppose for a contradiction that $\mathbf{R} \cup W$ induces an incomplete subgraph of $\mathcal{G}$. Since $\mathbf{R}$ induces a complete subgraph of $\mathcal{G}$, that means some vertex $R' \in \mathbf{R}$ is not adjacent with $W$. As $W \in {adj(X,\mathcal{G}) \backslash{(\mathbf{R} \cup pa(X,\mathcal{G}))}}$, the node $W$ can be a child or a sibling of $X$.
\begin{enumerate}[leftmargin=6.5mm]
   \itemsep0em
    \item [(1)] For the first case, as in \cref{fig: forproof_case1}, if $W$ is a child of $X$ in $\mathcal{G}$, since $W \rightarrow R$, then $X - R$ can be oriented by Rule 2 in Meek's criteria as $X \rightarrow R$, which contradicts that $R$ is a sibling of $X$;
    \item [(2)] For the second case, if $W$ is a sibling of $X$ in $\mathcal{G}$ and $W \rightarrow R$, then the edge between $R$ and $R'$ can not be an undirected edge in $\mathcal{G}$, since $R'$ and $W$ are not adjacent. $R \rightarrow R'$ can be oriented by Meek's Rule 2, or $R \leftarrow R'$ and $\langle R', R, W \rangle$ is a v-structure collided on $R$. For the former case, if $R \rightarrow R'$ is in $\mathcal{G}$ as in \cref{fig: forproof_case2}, then $X \rightarrow R'$ can be oriented by Rule 4, which contradicts that $R'$ is a sibling of $X$ in $\mathcal{G}$. For the latter case in \cref{fig: forproof_case3}, if $W$ is a sibling of $X$ in $\mathcal{G}$ and $W \rightarrow R \leftarrow R'$, since $R'$ and $W$ are not adjacent, then $X - R$ can be oriented as $X \rightarrow R$ in $\mathcal{G}$ by Meek's Rule 3, which contradicts that $R$ is a sibling of $X$. Therefore, there does not exist any vertex $R' \in \mathbf{R}$ not adjacent with $W$, so $\mathbf{R} \cup W$ induces a complete subgraph of $\mathcal{G}$.
\end{enumerate}

\begin{algorithmic}[1]
\caption{Identify the type of ancestral relation of $S$ with respect to all the other vertices in an MPDAG}
\label{alg: ancestral relation between X and all the other nodes}
\State \textbf{Input:} MPDAG $\mathcal{G}$, a variable $S$ in $\mathcal{G}$.
\State \textbf{Output:} The type of ancestral relation between $S$ and all the other vertices in $\mathcal{G}$.
\For{each node $W$ in $\mathcal{G}$}
    \State Identify the type of ancestral relation of $S$ with respect to $W$ in $\mathcal{G}$ by \cref{alg: ancestral relation between X and Y}.
\EndFor
\State \textbf{Return} the set of definite descendants, possible descendants and definite non-descendants of $S$ in $\mathcal{G}$.
\end{algorithmic}

